import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
import { join } from 'node:path'

const require = createRequire(join('/tmp/opencode/pw', 'package.json'))
const { chromium } = require('playwright-core')

const url = 'http://localhost:3002/'
const output = '/tmp/opencode/caps'
mkdirSync(output, { recursive: true })

let browser
let exitCode = 0
try {
  browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
    timeout: 30000,
  })
  for (const [name, width, height] of [
    ['desktop', 1440, 900],
    ['mobile', 390, 844],
  ]) {
    const page = await browser.newPage({ viewport: { width, height } })
    page.setDefaultTimeout(30000)
    const errors = []
    page.on('pageerror', (error) => errors.push(error.message))
    page.on('response', (response) => {
      if (response.status() >= 400 && new URL(response.url()).origin === new URL(url).origin) {
        errors.push(`HTTP ${response.status()}: ${response.url()}`)
      }
    })
    const response = await page.goto(url, { waitUntil: 'load', timeout: 45000 })
    if (!response?.ok()) throw new Error(`HTTP ${response?.status()} loading preview`)
    await page.locator('#app .shell').waitFor({ state: 'visible', timeout: 30000 })
    await page.locator('.stage-head h1').waitFor({ state: 'visible', timeout: 30000 })
    await page.waitForFunction(() => document.fonts.status === 'loaded', null, { timeout: 30000 })
    await page.waitForTimeout(1500)
    if (errors.length) throw new Error(`Page rendering failed: ${errors.join('; ')}`)
    await page.screenshot({ path: join(output, `final-${name}.jpg`), type: 'jpeg', quality: 85, fullPage: false })
    console.log(`Captured ${name} at ${url}`)
    await page.close()
  }
} catch (error) {
  console.error(error)
  exitCode = error.exitCode || 1
} finally {
  await browser?.close().catch(() => {})
  process.exitCode = exitCode
}

import { GENES, phenotype, MORPHOLOGY_FAMILIES } from '/home/runner/work/PlayGround/PlayGround/src/dna.js'

const families = new Set()
for (let i = 0; i < 300; i++) {
  // build a genome that produces morphologyIndex i via deterministic alleles
  const genome = {}
  for (const g of GENES) genome[g.key] = [0.5, 0.5]
  // set MORPHOLOGY_KEYS to force a specific hash value i
  const keys = ['size','length','girth','neck','head','snout','legs','stance','tail','armor','wings','posture','bodyPlan','archetype']
  // brute: just confirm the family names cover indices 0-299
  const p = phenotype(genome)
  families.add(p.morphologyFamily)
}
// confirm families count
console.log('families:', MORPHOLOGY_FAMILIES.length, 'unique families seen:', families.size)
console.log('last 10 families:', MORPHOLOGY_FAMILIES.slice(20).join(', '))

// Exercise all families by brute-forcing each morphologyIndex
const seen = new Set()
for (let target = 0; target < 300; target++) {
  for (let seed = 0; seed < 50000 && seen.size < 300; seed++) {
    const genome = {}
    const r = (() => { let a = seed >>> 0; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296 } })()
    for (const g of GENES) {
      const b = 0.5, spread = 0.34
      const c = Math.max(0.06, Math.min(0.96, b + (r() - 0.5) * spread))
      genome[g.key] = [Math.max(0.02, Math.min(0.98, c + (r() - 0.5) * 0.3)), Math.max(0.02, Math.min(0.98, c + (r() - 0.5) * 0.3))]
    }
    const p = phenotype(genome)
    if (p.morphologyIndex === target) { seen.add(target); break }
  }
}
console.log('morphology indices reachable:', seen.size, '/ 300')
if (seen.size < 300) {
  const missing = [...Array(300).keys()].filter(i => !seen.has(i))
  console.log('missing:', missing.slice(0, 20), missing.length > 20 ? `...+${missing.length-20}` : '')
}

